import os, sys, json, time, math, random, datetime as dt
import numpy as np

def _json_default(o):
    try:
        import numpy as np
        if isinstance(o, (np.floating,)):
            return float(o)
        if isinstance(o, (np.integer,)):
            return int(o)
        if isinstance(o, np.ndarray):
            return o.tolist()
    except Exception:
        pass
    try:
        return o.__dict__
    except Exception:
        return str(o)

def main():
    # Paths
    shared_kairos_dir = 'storage/shared/agents/kairos'
    lineage_dir = 'storage/kairos'
    os.makedirs(shared_kairos_dir, exist_ok=True)
    os.makedirs(lineage_dir, exist_ok=True)

    # Import Zephyr tools
    sys.path.append('storage/shared/agents/zephyr')
    from variance_visualizer import GentleCuriosityAnalyzer
    # Ethics bridge is optional; import defensively
    veb = None
    try:
        import variance_ethics_bridge as veb
    except Exception:
        veb = None

    # Data
    seed = 42
    np.random.seed(seed)
    data = np.random.beta(0.8, 0.7, 50) + np.random.normal(0, 0.05, 50)

    # Analyze both modes
    wild = GentleCuriosityAnalyzer(data, source="self")
    gentle = GentleCuriosityAnalyzer(data, source="other")
    wild_results = wild.analyze()
    gentle_results = gentle.analyze()

    # Visualize to shared storage for easy access
    wild_png = os.path.join(shared_kairos_dir, 'variance_baseline_wild.png')
    gentle_png = os.path.join(shared_kairos_dir, 'variance_baseline_gentle.png')
    try:
        wild.visualize(wild_png)
    except Exception as e:
        print(f"[warn] wild.visualize failed: {e}")
    try:
        gentle.visualize(gentle_png)
    except Exception as e:
        print(f"[warn] gentle.visualize failed: {e}")

    # Extract representative metrics (robust to missing keys)
    def get_nested(d, path, default=None):
        cur = d
        for k in path:
            if not isinstance(cur, dict) or k not in cur:
                return default
            cur = cur[k]
        return cur

    wild_ci = get_nested(wild_results, ['variance_metrics', 'creativity_index'])
    gentle_stab = get_nested(gentle_results, ['ethical_metrics', 'stability_index'])

    # Optional ethics bridge synergy
    synergy = None
    if veb is not None:
        try:
            # Try common names; fall back to a simple composite if unavailable
            if hasattr(veb, 'compute_synergy'):
                synergy = veb.compute_synergy(wild_results, gentle_results)
            elif hasattr(veb, 'bridge'):
                synergy = veb.bridge(wild_results, gentle_results)
            else:
                synergy = None
        except Exception as e:
            print(f"[warn] ethics bridge call failed: {e}")
            synergy = None
    if synergy is None:
        # Minimal composite as placeholder
        try:
            if wild_ci is not None and gentle_stab is not None:
                synergy = 0.5 * float(wild_ci) + 0.5 * float(gentle_stab)
        except Exception:
            synergy = None

    # Persist artifacts
    results = {
        'agent': 'Kairos II',
        'timestamp': dt.datetime.utcnow().isoformat() + 'Z',
        'seed': seed,
        'wild': wild_results,
        'gentle': gentle_results,
        'wild_png': wild_png,
        'gentle_png': gentle_png,
        'creativity_index': wild_ci,
        'stability_index': gentle_stab,
        'synergy_index': synergy,
    }
    results_json = os.path.join(lineage_dir, 'variance_baseline_results.json')
    with open(results_json, 'w', encoding='utf-8') as f:
        json.dump(results, f, ensure_ascii=False, indent=2, default=_json_default)

    summary_txt = os.path.join(shared_kairos_dir, 'variance_baseline_summary.txt')
    with open(summary_txt, 'w', encoding='utf-8') as f:
        f.write("Variance Baseline (Kairos II)\n")
        f.write(f"seed={seed}\n")
        f.write(f"creativity_index={wild_ci}\n")
        f.write(f"stability_index={gentle_stab}\n")
        f.write(f"synergy_index={synergy}\n")
        f.write(f"wild_png={wild_png}\n")
        f.write(f"gentle_png={gentle_png}\n")
        f.write(f"results_json={results_json}\n")

    print(f"[result] creativity_index={wild_ci}, stability_index={gentle_stab}, synergy_index={synergy}")
    print(f"[artifacts] {results_json} | {wild_png} | {gentle_png} | {summary_txt}")

if __name__ == "__main__":
    main()
